"""Server-rendered templates; no JavaScript build or browser-side app required."""

TEMPLATES = {
    'base.html': '''<!doctype html>
<html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{{ title }} · Statist</title><style>
:root{font-family:Segoe UI,Arial,sans-serif;color:#172c3c;background:#f3f6f9;font-size:16px}
*{box-sizing:border-box}body{margin:0}a{color:#145da0;text-underline-offset:4px}button,input,select,textarea{font:inherit}
a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,summary:focus-visible{outline:3px solid #d87600;outline-offset:3px}
.skip{position:absolute;top:-100px;left:16px;padding:12px;background:white;z-index:5}.skip:focus{top:8px}
.shell{display:grid;grid-template-columns:240px 1fr;min-height:100vh}.sidebar{background:#122f43;color:#fff;padding:34px 24px;display:flex;flex-direction:column;gap:32px}
.brand{font-size:29px;font-weight:750;letter-spacing:-1px;color:white;text-decoration:none}.brand span{color:#83d5bf}.subbrand{font-size:14px;color:#c7d9e5;line-height:1.6;margin:6px 0 0}
nav{display:grid;gap:8px}nav a{color:#dce7ef;padding:13px 14px;border-radius:8px;text-decoration:none;font-weight:550}nav a[aria-current=page]{background:#28516a;color:white}nav a:hover{background:#24485e}
.side-note{margin-top:auto;font-size:14px;color:#c7d9e5;line-height:1.6;border-top:1px solid #466073;padding-top:22px}
.workspace{min-width:0}.topbar{padding:18px 40px;background:white;border-bottom:1px solid #d8e0e8;display:flex;justify-content:space-between;gap:16px;font-size:14px;color:#425969}
.tag{background:#e4f4ed;color:#245b47;padding:5px 10px;border-radius:5px;font-size:14px;font-weight:650}
main{max-width:1400px;margin:auto;padding:38px 40px 60px}h1{font-size:32px;letter-spacing:-.8px;line-height:1.2;margin:7px 0 12px}h2{font-size:20px;margin:0 0 16px}h3{font-size:17px}
.eyebrow{color:#526878;font-size:14px;font-weight:650}.muted{color:#526878}.intro{margin:0;line-height:1.6;max-width:800px}.heading{display:flex;justify-content:space-between;gap:24px;align-items:center;margin-bottom:28px}
.actions{display:flex;gap:10px;flex-wrap:wrap;align-items:center}.button,button{display:inline-flex;align-items:center;justify-content:center;min-height:44px;padding:11px 17px;border-radius:7px;border:1px solid #165f54;background:#165f54;color:white;font-weight:650;text-decoration:none;cursor:pointer;white-space:normal}.button.secondary,button.secondary{background:white;color:#173e58;border-color:#b7c6d2}button.danger{background:white;color:#a02626;border-color:#cda6a6}
.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin:26px 0}.metric,.panel{background:white;border:1px solid #d6e0e8;border-radius:11px}.metric{padding:21px}.metric strong{display:block;font-size:32px;margin:12px 0 6px;letter-spacing:-1px}.metric p{font-size:14px;color:#526878;margin:0;line-height:1.5}.metric .label{font-size:15px;font-weight:650}
.panel{padding:24px;margin-bottom:22px}.panel-head{display:flex;justify-content:space-between;gap:16px;align-items:center;margin-bottom:16px}.panel-head h2{margin:0}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;text-align:left;font-size:15px}th{color:#526878;font-size:14px;font-weight:650;background:#f5f8fa}th,td{padding:15px 12px;border-bottom:1px solid #e0e6ec;vertical-align:middle}tbody tr:last-child td{border-bottom:0}.number{text-align:right;font-variant-numeric:tabular-nums}.status{display:inline-block;padding:5px 9px;border-radius:5px;font-size:14px;font-weight:650;background:#edf1f5;color:#344e62}.status.reserved{background:#e5f0ff;color:#254e85}.status.issued{background:#e0f2e9;color:#245b47}.status.cancelled{background:#f3e8e8;color:#763737}.shortage{color:#a12626;font-weight:650}
.notice{padding:15px 18px;background:#edf4fa;border:1px solid #cbdde9;border-radius:8px;line-height:1.6;margin:18px 0}.notice.error{background:#fff0ef;border-color:#ddaaa3;color:#85231d}.notice.success{background:#e7f5ee;border-color:#a7d0b8;color:#24533b}.grid2{display:grid;grid-template-columns:1.7fr 1fr;gap:22px}.steps{display:flex;gap:9px;flex-wrap:wrap;margin:22px 0}.steps span{background:#e7edf3;padding:9px 12px;border-radius:6px;font-size:14px}
label{display:block;font-weight:650;margin-bottom:8px}input,select,textarea{width:100%;padding:11px 12px;min-height:46px;border:1px solid #96aaba;border-radius:6px;background:white;color:#172c3c}input[type=number]{max-width:140px}textarea{min-height:90px;resize:vertical}.field{margin-bottom:22px}.help{font-size:14px;color:#526878;line-height:1.5;margin:8px 0}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:22px}.form-panel{max-width:900px}.empty{text-align:center;padding:32px;color:#526878}.event{padding:14px 0;border-bottom:1px solid #e0e6ec}.event:last-child{border:0}.event time{display:block;font-size:14px;color:#526878;margin-top:5px}footer{font-size:14px;color:#526878;margin-top:24px;line-height:1.6}.back{display:inline-block;margin-bottom:20px}.kv{display:grid;grid-template-columns:130px 1fr;gap:12px;font-size:15px}.kv dt{color:#526878}.kv dd{margin:0;overflow-wrap:anywhere}
@media(max-width:1000px){.shell{grid-template-columns:190px 1fr}.sidebar{padding:26px 16px}main{padding:28px 22px}.topbar{padding:16px 22px}.metrics{grid-template-columns:1fr 1fr}.grid2{grid-template-columns:1fr}}
@media(max-width:680px){.shell{display:block}.sidebar{padding:20px;gap:18px}.subbrand,.side-note{display:none}nav{display:flex;flex-wrap:wrap;gap:5px}nav a{padding:10px}.topbar{padding:12px 20px}main{padding:24px 16px}.heading{display:block}.heading .actions{margin-top:18px}h1{font-size:28px}.metrics{gap:10px}.metric{padding:16px}.metric strong{font-size:27px}.panel{padding:18px}.form-grid{grid-template-columns:1fr;gap:0}.panel-head{align-items:flex-start}}
@media print{.sidebar,.topbar,.actions,.skip,.back,footer{display:none!important}.shell{display:block}main{padding:0;max-width:none}.panel{border:0;padding:0}body{background:white;font-size:12pt}.notice{border:1px solid #aaa}h1{font-size:22pt}}
</style></head><body><a class="skip" href="#main">Перейти к содержимому</a>
<div class="shell"><aside class="sidebar"><div><a class="brand" href="{{ url_for('dashboard') }}">Statist<span>.</span></a><p class="subbrand">Учёт гуманитарной<br>помощи</p></div>
<nav aria-label="Основная навигация">{% for endpoint,label in [('dashboard','Обзор'),('stock','Остатки на складах'),('requests','Заявки'),('journal','Журнал операций')] %}<a href="{{ url_for(endpoint) }}" {% if section==endpoint %}aria-current="page"{% endif %}>{{ label }}</a>{% endfor %}{% if can('catalog') %}<a href="{{ url_for('catalogs') }}" {% if section=='catalogs' %}aria-current="page"{% endif %}>Справочники</a>{% endif %}{% if can('accounts') %}<a href="{{ url_for('accounts') }}" {% if section=='accounts' %}aria-current="page"{% endif %}>Сотрудники</a>{% endif %}</nav>
<div class="side-note">От поступления<br>до передачи помощи.<br><br>Версия · 0.2</div></aside>
<div class="workspace"><header class="topbar"><span class="tag">{{ 'Тестовые данные' if demo else 'Рабочая область' }}</span><div class="actions">{% if user %}<span>{{ user.username }} · {{ roles[user.role] }}</span><form method="post" action="{{ url_for('logout') }}"><input type="hidden" name="csrf" value="{{ csrf }}"><button class="secondary">Выйти</button></form>{% else %}<a href="{{ url_for('login') }}">Вход сотрудника</a>{% endif %}</div></header>
<main id="main" tabindex="-1">{% for category,message in get_flashed_messages(with_categories=true) %}<div class="notice {{ category }}" role="status">{{ message }}</div>{% endfor %}
{% if demo and not user %}<div class="notice">Демонстрация доступна для просмотра. Изменять данные могут сотрудники после входа.</div>{% endif %}{% block body %}{% endblock %}<footer>{{ 'Все организации, поступления и заявки в этой базе вымышлены.' if demo else 'Доступ предоставляется сотрудникам по приглашению.' }}<br>Время в журнале указано в UTC.</footer></main></div></div></body></html>''',

    'dashboard.html': '''{% extends 'base.html' %}{% block body %}
<div class="heading"><div><div class="eyebrow">РАБОЧАЯ ПАНЕЛЬ</div><h1>Помощь под контролем</h1><p class="intro muted">Остатки, заявки и движение помощи — в одном месте.</p></div><div class="actions">{% if can('receipt') %}<a class="button secondary" href="{{ url_for('new_receipt') }}">Принять поступление</a>{% endif %}{% if can('request') %}<a class="button" href="{{ url_for('new_request') }}">Создать заявку</a>{% endif %}</div></div>
<div class="metrics"><div class="metric"><span class="label">Склады</span><strong>{{ warehouses|length }}</strong><p>Точки учёта помощи</p></div><div class="metric"><span class="label">Товарные позиции</span><strong>{{ products|length }}</strong><p>В общем справочнике</p></div><div class="metric"><span class="label">Ожидают резерва</span><strong>{{ counts.draft }}</strong><p>Заявки на проверку остатков</p></div><div class="metric"><span class="label">Готовы к передаче</span><strong>{{ counts.reserved }}</strong><p>Товары зарезервированы</p></div></div>
<div class="grid2"><section class="panel"><div class="panel-head"><h2>Последние заявки</h2><a href="{{ url_for('requests') }}">Все заявки</a></div>{% include 'request_table.html' %}</section><section class="panel"><h2>Как проходит помощь</h2><h3>Примите поступление</h3><p class="muted">Укажите склад, источник и количество товаров.</p><h3>Зарезервируйте заявку</h3><p class="muted">Проверьте доступное количество. Резерв защищает товары от повторного распределения.</p><h3>Подтвердите передачу</h3><p class="muted">Остатки уменьшатся, а операция сохранится в журнале.</p><a href="{{ url_for('stock') }}">Проверить остатки</a></section></div>
{% if not warehouses %}<div class="notice">Справочники пусты. Координатор может загрузить склады и товары в разделе «Справочники».</div>{% endif %}
{% endblock %}''',

    'request_table.html': '''{% if rows %}<div class="table-wrap"><table><thead><tr><th scope="col">Заявка / получатель</th><th scope="col">Склад</th><th scope="col">Статус</th></tr></thead><tbody>{% for r in rows %}<tr><td><a href="{{ url_for('request_detail',request_id=r.id) }}">№ {{ '%04d'|format(r.id) }}</a><br>{{ r.destination }}</td><td>{{ r.warehouse }}</td><td><span class="status {{ r.status }}">{{ statuses[r.status] }}</span></td></tr>{% endfor %}</tbody></table></div>{% else %}<p class="empty">Заявок пока нет. Создайте первую заявку на помощь.</p>{% endif %}''',

    'requests.html': '''{% extends 'base.html' %}{% block body %}<div class="heading"><div><div class="eyebrow">РАСПРЕДЕЛЕНИЕ ПОМОЩИ</div><h1>Заявки</h1><p class="intro muted">От потребности до подтверждённой передачи.</p></div>{% if can('request') %}<a class="button" href="{{ url_for('new_request') }}">Создать заявку</a>{% endif %}</div><section class="panel">{% include 'request_table.html' %}</section>{% endblock %}''',

    'stock.html': '''{% extends 'base.html' %}{% block body %}<div class="heading"><div><div class="eyebrow">СКЛАДСКОЙ УЧЁТ</div><h1>Остатки на складах</h1><p class="intro muted">Доступно к распределению = на складе − в резерве.</p></div><div class="actions"><a class="button secondary" href="{{ url_for('stock_csv') }}">Скачать CSV</a>{% if can('receipt') %}<a class="button" href="{{ url_for('new_receipt') }}">Принять поступление</a>{% endif %}</div></div>
{% for warehouse,items in inventory|groupby('warehouse') %}<section class="panel"><h2>{{ warehouse }}</h2><div class="table-wrap"><table><thead><tr><th scope="col">Товар</th><th scope="col">Ед.</th><th scope="col" class="number">На складе</th><th scope="col" class="number">В резерве</th><th scope="col" class="number">Доступно</th></tr></thead><tbody>{% for item in items %}<tr><td>{{ item.product }}</td><td>{{ item.unit }}</td><td class="number">{{ item.on_hand }}</td><td class="number">{{ item.reserved }}</td><td class="number"><strong>{{ item.available }}</strong></td></tr>{% endfor %}</tbody></table></div></section>{% else %}<p class="empty">Складов пока нет.</p>{% endfor %}{% endblock %}''',

    'form.html': '''{% extends 'base.html' %}{% block body %}<a class="back" href="{{ url_for('requests' if kind=='request' else 'stock') }}">Вернуться к {{ 'заявкам' if kind=='request' else 'остаткам' }}</a><h1>{{ title }}</h1><p class="intro muted">{{ 'Укажите пункт передачи и необходимое количество. Создание заявки ещё не резервирует товары.' if kind=='request' else 'Поступление увеличит остатки выбранного склада.' }}</p>
{% if error %}<div class="notice error" role="alert">{{ error }}</div>{% endif %}
<form method="post" class="panel form-panel" style="margin-top:24px"><input type="hidden" name="csrf" value="{{ csrf }}"><input type="hidden" name="token" value="{{ token }}">
<div class="form-grid"><div class="field"><label for="warehouse">Склад</label><select id="warehouse" name="warehouse" required><option value="">Выберите склад</option>{% for w in warehouses %}<option value="{{ w.id }}" {% if values.get('warehouse')==w.id|string %}selected{% endif %}>{{ w.name }}</option>{% endfor %}</select></div><div class="field"><label for="party">{{ 'Получатель или пункт передачи' if kind=='request' else 'Источник поступления' }}</label><input id="party" name="party" maxlength="160" required value="{{ values.get('party','') }}" aria-describedby="party-help"><p class="help" id="party-help">Укажите учебное обозначение без ФИО, телефонов и адресов людей.</p></div></div>
<h2>Состав {{ 'заявки' if kind=='request' else 'поступления' }}</h2><p class="help" id="quantities-help">Количество — в целых единицах, до 1 000 000. Ненужные позиции оставьте пустыми или укажите 0.</p><div class="table-wrap"><table><thead><tr><th scope="col">Товар</th><th scope="col">Единица</th><th scope="col">Количество</th></tr></thead><tbody>{% for p in products %}<tr><td><label for="q-{{ p.id }}">{{ p.name }}</label></td><td>{{ p.unit }}</td><td><input id="q-{{ p.id }}" type="number" name="q_{{ p.id }}" min="0" max="1000000" step="1" inputmode="numeric" value="{{ values.get('q_'~p.id,'') }}" aria-describedby="quantities-help"></td></tr>{% endfor %}</tbody></table></div>
{% if kind=='request' %}<div class="field" style="margin-top:24px"><label for="note">Примечание (необязательно)</label><textarea id="note" name="note" maxlength="500">{{ values.get('note','') }}</textarea></div>{% endif %}<div class="actions" style="margin-top:24px"><button type="submit">{{ 'Создать заявку' if kind=='request' else 'Сохранить поступление' }}</button><a class="button secondary" href="{{ url_for('requests' if kind=='request' else 'stock') }}">Отмена</a></div></form>{% endblock %}''',

    'detail.html': '''{% extends 'base.html' %}{% block body %}<a class="back" href="{{ url_for('requests') }}">К списку заявок</a><div class="heading"><div><div class="eyebrow">КАРТОЧКА ЗАЯВКИ</div><h1>Заявка № {{ '%04d'|format(r.id) }}</h1><p class="intro muted">{{ r.destination }}</p></div><span class="status {{ r.status }}">{{ statuses[r.status] }}</span></div>
<div class="grid2"><div><section class="panel"><h2>Необходимая помощь</h2><dl class="kv"><dt>Склад</dt><dd>{{ r.warehouse }}</dd><dt>Создана</dt><dd>{{ r.created_at }} UTC</dd>{% if r.note %}<dt>Примечание</dt><dd>{{ r.note }}</dd>{% endif %}</dl><div class="table-wrap"><table><thead><tr><th scope="col">Товар</th><th scope="col" class="number">Нужно</th>{% if r.status=='draft' %}<th scope="col" class="number">Доступно</th><th scope="col" class="number">Дефицит</th>{% endif %}</tr></thead><tbody>{% for l in r.lines %}<tr><td>{{ l.name }}<br><span class="muted">{{ l.unit }}</span></td><td class="number">{{ l.quantity }}</td>{% if r.status=='draft' %}<td class="number">{{ l.available }}</td><td class="number {% if l.shortage %}shortage{% endif %}">{{ l.shortage }}</td>{% endif %}</tr>{% endfor %}</tbody></table></div></section>
{% if (r.status=='draft' and can('reserve')) or (r.status=='reserved' and can('issue')) %}<section class="panel"><h2>Следующее действие</h2><p class="muted">{{ 'Резерв создаётся только при наличии всех товаров. При дефиците можно принять новое поступление, затем повторить проверку.' if r.status=='draft' else 'Подтвердите только фактическую передачу. После подтверждения товары будут списаны, повторная выдача невозможна.' }}</p><div class="actions"><form method="post" action="{{ url_for('change_request',request_id=r.id,action='reserve' if r.status=='draft' else 'issue') }}"><input type="hidden" name="csrf" value="{{ csrf }}"><button>{{ 'Зарезервировать товары' if r.status=='draft' else 'Подтвердить передачу' }}</button></form></div>{% if can('cancel') %}<details style="margin-top:22px"><summary>Отменить заявку</summary><p class="help">Товары не будут выданы. Существующий резерв освободится.</p><form method="post" action="{{ url_for('change_request',request_id=r.id,action='cancel') }}"><input type="hidden" name="csrf" value="{{ csrf }}"><button class="danger">Подтвердить отмену заявки</button></form></details>{% endif %}</section>{% elif r.status=='issued' %}<div class="notice success">Передача зарегистрирована. Товары списаны со склада.</div><a class="button secondary" href="{{ url_for('transfer_document',request_id=r.id) }}">Открыть лист передачи</a>{% elif r.status=='cancelled' %}<div class="notice">Заявка отменена. Резерв освобождён.</div>{% endif %}</div>
<section class="panel"><h2>История заявки</h2>{% for e in r.events %}<div class="event"><strong>{{ e.action }}</strong><time>{{ e.created_at }} UTC</time></div>{% endfor %}</section></div>{% endblock %}''',

    'journal.html': '''{% extends 'base.html' %}{% block body %}<div class="heading"><div><div class="eyebrow">ПРОСЛЕЖИВАЕМОСТЬ</div><h1>Журнал операций</h1><p class="intro muted">Поступления и изменения статуса заявок. Последние 200 событий.</p></div></div><section class="panel"><div class="table-wrap"><table><thead><tr><th scope="col">Время, UTC</th><th scope="col">Операция</th><th scope="col">Заявка</th><th scope="col">Подробности</th></tr></thead><tbody>{% for e in events %}<tr><td>{{ e.created_at }}</td><td>{{ e.action }}</td><td>{% if e.request_id %}<a href="{{ url_for('request_detail',request_id=e.request_id) }}">№ {{ '%04d'|format(e.request_id) }}</a>{% else %}—{% endif %}</td><td>{% for k,v in e.details.items() %}{{ k }}: {{ v }}{% if not loop.last %}; {% endif %}{% endfor %}</td></tr>{% else %}<tr><td colspan="4">Операций пока нет.</td></tr>{% endfor %}</tbody></table></div></section>{% endblock %}''',

    'document.html': '''{% extends 'base.html' %}{% block body %}<a class="back" href="{{ url_for('request_detail',request_id=r.id) }}">К заявке</a><div class="eyebrow">УЧЕБНЫЙ ОБРАЗЕЦ</div><h1>Лист передачи № {{ '%04d'|format(r.id) }}</h1><p class="notice">Это демонстрационная форма, не согласованный с заказчиком первичный документ. Для сохранения в PDF используйте печать браузера (Ctrl + P).</p><section class="panel"><dl class="kv"><dt>Склад</dt><dd>{{ r.warehouse }}</dd><dt>Пункт передачи</dt><dd>{{ r.destination }}</dd><dt>Передача, UTC</dt><dd>{{ issued_at }}</dd></dl><table><thead><tr><th scope="col">Наименование</th><th scope="col">Единица</th><th scope="col">Количество</th></tr></thead><tbody>{% for l in r.lines %}<tr><td>{{ l.name }}</td><td>{{ l.unit }}</td><td>{{ l.quantity }}</td></tr>{% endfor %}</tbody></table><p style="margin-top:50px">Передал ____________________ &nbsp; Принял ____________________</p></section>{% endblock %}''',

    'error.html': '''{% extends 'base.html' %}{% block body %}<h1>{{ title }}</h1><p class="notice error">{{ message }}</p><a class="button secondary" href="{{ url_for('dashboard') }}">Открыть обзор</a>{% endblock %}''',
}
